spec.expr:
max without(instance, job, type) (
  label_join(
    label_join(
      (
        drift_metric_value{feature!="prediction"}
        and on(feature)
        (
          drift_status_feature{feature!="prediction"}
          ${analysis_status_filter:raw}
        )
      ),
      "join_key",
      "",
      "feature"
    ),
    "join_key",
    "::",
    "join_key",
    "metric"
  )
)

max without(feature, type, metric, instance, job) (
  label_join(
    label_join(
      (
        label_replace(
          drift_status{feature!="prediction"} == 1,
          "alert", "${1} warning", "metric", "(.+)"
        )
        or
        label_replace(
          drift_status{feature!="prediction"} == 2,
          "alert", "${1} critical", "metric", "(.+)"
        )
      )
      and on(feature)
      (
        drift_status_feature{feature!="prediction"}
        ${analysis_status_filter:raw}
      ),
      "join_key",
      "",
      "feature"
    ),
    "join_key",
    "::",
    "join_key",
    "metric"
  )
)

max without(instance, job, type, metric) (
  drift_metric_value{
    feature!="prediction",
    metric="psi"
  }
  and on(feature)
  (
    drift_status_feature{feature!="prediction"}
    ${analysis_status_filter:raw}
  )
)

(
  (
    # Значения метрик
    drift_metric_value{feature!="prediction"}

    or

    # Статусы отдельных метрик
    label_replace(
      drift_status{feature!="prediction"},
      "metric", "${1}_status", "metric", "(.+)"
    )

    or

    # Общий feature status
    label_replace(
      drift_status_feature{feature!="prediction"},
      "metric", "___Status", "feature", ".+"
    )
  )

  # Фильтр всех полученных данных по статусу фичи
  and on(feature)
  (
    drift_status_feature{feature!="prediction"}
    ${analysis_status_filter:raw}
  )
)

# Fallback
or on()
label_replace(
  label_replace(
    vector(-1),
    "feature", "Collecting data", "", ""
  ),
  "metric", "Loading", "", ""
)
